from pathlib import Path
import json,hashlib,re,collections
OUT=Path(__file__).resolve().parent
TB=Path('/Users/nene/Documents/fpv-1/toolbox2_source/APPS/TOOLBOX2')
AERO=Path('/Users/nene/Documents/fpv-1/radiomaster_tx16s_mkII/LUA')
MAIN=AERO/'sdcard/SCRIPTS/TOOLS/telem.lua'
CLIENT=AERO/'sdcard/SCRIPTS/TOOLS/AERODECK/crsf-msp.lua'
DECODER=AERO/'sdcard/SCRIPTS/TOOLS/AERODECK/arm-status.lua'
index=json.loads((OUT/'evidence/original-file-index.json').read_text())
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def source(name,line,extra=None):
 p=TB/(name+'.lua'); d={'file':str(p),'line':line,'kind':'recovered-source','sha256':sha(p)}
 if extra:d['note']=extra
 return d
def aero(line,file=MAIN):return {'file':str(file),'line':line,'kind':'aerodeck-source','sha256':sha(file)}
def orig(name,match=None,note=None):
 ent=next(e for e in index if e['original'].endswith('/'+name+'.luac'));p=Path(ent['evidence']);lines=p.read_text().splitlines()
 needle=re.sub(r'^K[0-9]+ ', '', match or '')
 line=next((i+1 for i,s in enumerate(lines) if needle in s),0) if needle else 1
 if not line and needle.startswith("'") and needle.endswith("'"):
  line=next((i+1 for i,s in enumerate(lines) if needle[1:-1] in s),0)
 if not line: line=next((i+1 for i,s in enumerate(lines) if s.startswith('FUNCTION main ')),1)
 d={'file':str(p.resolve()),'line':line,'kind':'original-bytecode-disassembly','originalFile':str(Path(ent['original']).resolve()),'sha256':ent['sha256']}
 if note:d['note']=note
 return d
